// Gerar número único de pedido
const agora = new Date();
const timestamp = agora.getTime();
const random = Math.floor(Math.random() * 1000).toString().padStart(3, '0');
const numeroPedido = `PED${agora.getFullYear()}${(agora.getMonth()+1).toString().padStart(2,'0')}${agora.getDate().toString().padStart(2,'0')}-${random}`;

const dadosPedido = $json;

// Validar dados obrigatórios
if (!dadosPedido.cliente_id) {
  throw new Error('cliente_id é obrigatório');
}

if (!dadosPedido.itens || dadosPedido.itens.length === 0) {
  throw new Error('Pedido deve ter pelo menos um item');
}

// Calcular valores
let subtotal = 0;
dadosPedido.itens.forEach(item => {
  const itemSubtotal = item.preco_unitario * item.quantidade;
  item.subtotal = itemSubtotal;
  subtotal += itemSubtotal;
});

const taxaEntrega = dadosPedido.tipo === 'delivery' ? parseFloat(dadosPedido.taxa_entrega || 5.00) : 0;
const desconto = parseFloat(dadosPedido.desconto || 0);
const total = subtotal + taxaEntrega - desconto;

// Calcular tempo estimado (baseado no item com maior tempo de preparo)
let tempoEstimado = 0;
if (dadosPedido.tipo === 'delivery') {
  tempoEstimado = 40; // tempo padrão de entrega
} else {
  tempoEstimado = 30; // tempo padrão de retirada
}

const previsaoEntrega = new Date(agora.getTime() + tempoEstimado * 60000);

return {
  json: {
    numero_pedido: numeroPedido,
    cliente_id: dadosPedido.cliente_id,
    tipo: dadosPedido.tipo || 'delivery',
    subtotal: subtotal.toFixed(2),
    taxa_entrega: taxaEntrega.toFixed(2),
    desconto: desconto.toFixed(2),
    total: total.toFixed(2),
    forma_pagamento: dadosPedido.forma_pagamento || 'dinheiro',
    troco_para: dadosPedido.troco_para || null,
    observacoes: dadosPedido.observacoes || null,
    tempo_estimado: tempoEstimado,
    previsao_entrega: previsaoEntrega.toISOString(),
    status: 'novo',
    itens: dadosPedido.itens
  }
};

// Preparar itens para inserção
const pedidoId = $json.id;
const itens = $('Processar Dados do Pedido').first().json.itens;

return itens.map(item => ({
  json: {
    pedido_id: pedidoId,
    produto_id: item.produto_id,
    quantidade: item.quantidade,
    tamanho: item.tamanho || null,
    preco_unitario: item.preco_unitario,
    subtotal: item.subtotal,
    observacoes: item.observacoes || null,
    adicionais: item.adicionais || null,
    remocoes: item.remocoes || null
  }
}));

// Formatar mensagem de confirmação do pedido
const pedido = $json;

let mensagem = `✅ *PEDIDO CONFIRMADO*\n\n`;
mensagem += `📋 *Número:* ${pedido.numero_pedido}\n`;
mensagem += `👤 *Cliente:* ${pedido.cliente_nome}\n\n`;

mensagem += `🍕 *Itens do Pedido:*\n`;
pedido.itens.forEach((item, idx) => {
  mensagem += `${idx + 1}. ${item.nome_produto}`;
  if (item.tamanho) mensagem += ` (${item.tamanho})`;
  mensagem += ` x${item.quantidade} - R$ ${parseFloat(item.subtotal).toFixed(2)}\n`;
  if (item.observacoes) mensagem += `   _${item.observacoes}_\n`;
});

mensagem += `\n💰 *Valores:*\n`;
mensagem += `Subtotal: R$ ${parseFloat(pedido.subtotal).toFixed(2)}\n`;
if (parseFloat(pedido.taxa_entrega) > 0) {
  mensagem += `Taxa de Entrega: R$ ${parseFloat(pedido.taxa_entrega).toFixed(2)}\n`;
}
if (parseFloat(pedido.desconto) > 0) {
  mensagem += `Desconto: -R$ ${parseFloat(pedido.desconto).toFixed(2)}\n`;
}
mensagem += `*Total: R$ ${parseFloat(pedido.total).toFixed(2)}*\n\n`;

mensagem += `💳 *Pagamento:* ${pedido.forma_pagamento}\n`;
if (pedido.troco_para) {
  mensagem += `💵 Troco para: R$ ${parseFloat(pedido.troco_para).toFixed(2)}\n`;
}

mensagem += `\n`;
if (pedido.tipo === 'delivery') {
  mensagem += `🛵 *Entrega:* ${pedido.tempo_estimado} minutos\n`;
  mensagem += `📍 *Endereço:* ${pedido.cliente_endereco}\n`;
} else if (pedido.tipo === 'retirada') {
  mensagem += `🏪 *Retirada:* ${pedido.tempo_estimado} minutos\n`;
}

if (pedido.observacoes) {
  mensagem += `\n📝 *Observações:* ${pedido.observacoes}\n`;
}

mensagem += `\nObrigado pela preferência! 🍕❤️`;

return {
  json: {
    pedido_id: pedido.id,
    numero_pedido: pedido.numero_pedido,
    telefone: pedido.cliente_telefone,
    mensagem_confirmacao: mensagem,
    pedido_completo: pedido
  }
};

const pedido = $json;

const mensagensStatus = {
  'confirmado': `✅ Seu pedido *${pedido.numero_pedido}* foi confirmado!\n\nEstamos preparando com carinho. Tempo estimado: ${pedido.tempo_estimado} minutos.`,
  'preparando': `👨‍🍳 Seu pedido *${pedido.numero_pedido}* está sendo preparado!\n\nEm breve estará pronto. 🍕`,
  'saiu_entrega': `🛵 Seu pedido *${pedido.numero_pedido}* saiu para entrega!\n\nChega em breve. Bom apetite! 😋`,
  'entregue': `✅ Pedido *${pedido.numero_pedido}* entregue!\n\nObrigado pela preferência! Avalie seu pedido: [link avaliação]`,
  'cancelado': `❌ Pedido *${pedido.numero_pedido}* cancelado.\n\n${pedido.motivo_cancelamento ? 'Motivo: ' + pedido.motivo_cancelamento : 'Entre em contato para mais informações.'}`
};

const mensagem = mensagensStatus[pedido.status] || `Status do pedido ${pedido.numero_pedido} atualizado para: ${pedido.status}`;

return {
  json: {
    telefone: pedido.telefone,
    mensagem: mensagem,
    pedido_numero: pedido.numero_pedido,
    status: pedido.status
  }
};
